INSERT INTO knowledge.source_claim (claim_id, claim_code, source_version_id, chapter_id, chunk_id, page_start, page_end, claim_type, claim_kind, claim_text, knowledge_type, contract, confidence, status) VALUES
   ('fe8ed9e5-5f09-552b-8cd7-6806f31ce04b', 'BNR-0008', 'NELSON_ILLUSTRATED_2017', 'BN-C01', 'eaf04089-8b6a-5d90-9569-56dc0394cb66', '183', '183', 'PAEDIATRIC_RESPIRATORY', 'threshold', 'Acute asthma severity assessment (mild / moderate / severe): consciousness (absent vs agitated-confused), cyanosis (absent vs likely), dyspnoea (walking vs talking vs at rest), speech (sentences vs phrases vs words), pulse (normal vs mild vs marked tachycardia, >180 bpm in young), pulsus paradoxus (normal vs <20 vs 20-40 mmHg), wheeze (end-expiratory vs holosystolic vs exp+insp, may be quiet), retractions (absent vs common vs usual), peak expiratory flow (>=70% vs 40-69% vs <40%), oximetry in air (>95% vs 90-95% vs <90%), PaCO2 (<42 vs >42 mmHg).', 'medicine', '{"what_is_it":"paediatric asthma severity grid","what_fact_produces":"SPEECH_PATTERN, SPO2, PEF, HEART_RATE, WHEEZE_PRESENT, CYANOSIS","source_support":"Illustrated Baby Nelson p183"}'::jsonb, 0.9, 'VERIFIED'),
   ('b8781f55-feec-5c00-9374-61248ee84c22', 'BNR-0009', 'NELSON_ILLUSTRATED_2017', 'BN-C01', 'eaf04089-8b6a-5d90-9569-56dc0394cb66', '183', '183', 'PAEDIATRIC_RESPIRATORY', 'management', 'Emergency department treatment of acute asthma exacerbation: inhaled SABA (salbutamol) 2.5-5 mg by nebulizer with saline up to 3 treatments in 1 hour OR 2-6 puffs SABA by MDI (puff=100 mcg); ipratropium bromide 125-250 mcg by nebulizer if no adequate response to the first salbutamol nebulizer (repeat every 20 minutes for the first hour only); oral corticosteroids 1-2 mg/kg in divided doses in moderate to severe exacerbations to hasten recovery and prevent recurrence; epinephrine (1:1000) 0.3-0.5 mg IM or SC may be given in severe cases.', 'guideline_activity', '{"what_is_it":"acute asthma ED treatment","what_connects_to":"protocol step (acute asthma)","source_support":"Illustrated Baby Nelson p183"}'::jsonb, 0.9, 'VERIFIED'),
   ('e1623fd6-c7b6-5bb1-bed4-525d81901bf4', 'BNR-0010', 'NELSON_ILLUSTRATED_2017', 'BN-C01', 'eaf04089-8b6a-5d90-9569-56dc0394cb66', '183', '183', 'PAEDIATRIC_RESPIRATORY', 'red_flag', 'Signs of acute severe asthma with imminent respiratory arrest: drowsy or confused, paradoxical thoracoabdominal movement, absence of wheeze, bradycardia and absent pulsus paradoxus (due to respiratory muscle fatigue).', 'medicine', '{"what_is_it":"imminent arrest asthma signs","what_fact_produces":"CONFUSION, CYANOSIS, WHEEZE_PRESENT","source_support":"Illustrated Baby Nelson p183"}'::jsonb, 0.9, 'VERIFIED'),
   ('2c3790e2-848a-55c2-b522-daaf9275bc5a', 'BNR-0011', 'NELSON_ILLUSTRATED_2017', 'BN-C01', 'd00bcd9e-a52b-5cac-adf8-0db3493f2071', '185', '185', 'PAEDIATRIC_RESPIRATORY', 'management', 'Hospital/PICU admission for asthma: PICU is indicated for severe respiratory distress or concern for potential respiratory failure and arrest. Inpatient action plan: cardio-pulmonary monitoring, oxygen, salbutamol nebulizer every 20 min as needed then every 1-4 hr, or continuous nebulization with oxygen 5-15 mg/hr; corticosteroids short course 3-7 days (oral prednisone 1-2 mg/kg, or parenteral methylprednisolone or hydrocortisone); ipratropium bromide nebulizer (poor evidence, no longer recommended).', 'guideline_activity', '{"what_is_it":"hospital/PICU asthma care","what_connects_to":"protocol step (acute asthma)","source_support":"Illustrated Baby Nelson p185"}'::jsonb, 0.9, 'VERIFIED'),
   ('228bc75c-3050-5963-aac7-e874113fa744', 'BNR-0012', 'NELSON_ILLUSTRATED_2017', 'BN-C01', '29895463-fd2b-5584-ab57-46065073a0f7', '186', '186', 'PAEDIATRIC_RESPIRATORY', 'management', 'After asthma exacerbation resolution: space SABA gradually; continue steroids for the full 3-7 days; start controller therapy; families of all children with asthma should have a written action plan to guide recognition and management of exacerbations; with a history of life-threatening episodes, especially abrupt-onset, consider providing an epinephrine autoinjector and possibly portable oxygen at home.', 'guideline_activity', '{"what_is_it":"post-exacerbation asthma action plan","what_connects_to":"education (action plan), controller therapy","source_support":"Illustrated Baby Nelson p186"}'::jsonb, 0.9, 'VERIFIED')
