INSERT INTO knowledge.protocol_condition (id, protocol_id, condition_id, is_primary) VALUES
   ('99e1550b-53fd-59c8-8a68-ae8fed6e5e5a', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT id FROM knowledge.condition WHERE condition_code = 'ASTHMA'), true)
INSERT INTO knowledge.protocol_step (id, protocol_id, step_code, step_label, step_type, sequence_no, instruction, rationale, required) VALUES
   ('65c502fa-4ead-5ddc-ad11-f37454c3b4f1', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-01', 'Confirm acute asthma presentation', 'eligibility', '10', 'Establish recurrent/presenting wheeze, cough, dyspnoea and chest tightness with variable obstruction; elicit triggers, nocturnal symptoms and atopic history.', 'Asthma is episodic and variable; triggers and atopy support the diagnosis.', TRUE),
   ('01223c58-47eb-5d7f-9a3c-c375e4127c55', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-02', 'Assess severity immediately', 'red_flag', '20', 'Grade mild/moderate/severe by consciousness, speech (sentences/phrases/words), pulse, pulsus paradoxus, wheeze, retractions, PEF, oximetry in air and cyanosis.', 'Severity grading drives treatment intensity and disposition (BNR-0008).', TRUE),
   ('c0610765-6e76-5bac-a04e-504df142f463', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-03', 'Screen for imminent respiratory arrest', 'red_flag', '30', 'Look for drowsy/confused state, paradoxical thoracoabdominal movement, absence of wheeze, bradycardia and absent pulsus paradoxus.', 'Respiratory muscle fatigue precedes arrest; these signs mandate immediate escalation (BNR-0010).', TRUE),
   ('faf8cb49-9549-566a-9209-8710bd2817a3', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-04', 'Deliver emergency treatment', 'treatment', '40', 'High-flow oxygen to keep SpO2 >92%; salbutamol 2.5-5 mg nebulizer or 2-6 puffs MDI repeated up to 3 treatments in the first hour; ipratropium 125-250 mcg nebulizer if no response to first salbutamol (first hour only); oral corticosteroids 1-2 mg/kg in moderate-severe; epinephrine 0.3-0.5 mg IM/SC in severe cases.', 'Rapid bronchodilation + corticosteroids shorten recovery and prevent recurrence (BNR-0009).', TRUE),
   ('14a0d8a0-7884-510c-b23b-07dcbf0c4349', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-05', 'Monitor response', 'monitoring', '50', 'Reassess at 1 hour: PEF >70% predicted/personal best, SpO2 >92% in room air for 4 hours, normal physical findings; trend pulse, respiratory effort and wheeze.', 'Outcome at 1 hour determines discharge, admission or escalation (BNR-0009).', TRUE),
   ('53eb4e9a-7f4c-5ac0-8c7f-8e9d4ed7c92b', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-06', 'Determine disposition', 'disposition', '60', 'Good outcome at 1 hour: discharge home with written action plan. Moderate-severe not improving after 1-2 hours of intensive treatment: admit. Severe respiratory distress or concern for respiratory failure/arrest: PICU.', 'High-risk patients (previous ICU admission, 2+ hospitalisations or 3+ ED visits in past year) warrant admission (BNR-0011).', TRUE),
   ('49ff79b5-6614-5f04-978c-81b46078ec18', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-07', 'Provide hospital care', 'treatment', '70', 'Cardio-pulmonary monitoring, oxygen, salbutamol nebulizer every 20 min then every 1-4 hours, or continuous nebulization 5-15 mg/hr; oral prednisolone 1-2 mg/kg or parenteral methylprednisolone/hydrocortisone for 3-7 days.', 'Inpatient care delivers intensive bronchodilation and corticosteroids under observation (BNR-0011).', TRUE),
   ('5ab2a39f-12af-515b-8f30-85bebcc7cf34', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-08', 'Escalate for persistent severe / critical illness', 'escalation', '80', 'If persistent severe dyspnoea with high-flow oxygen requirements: IV access, electrolytes/glucose/ABG, CXR if life-threatening or suspected pneumothorax, IV maintenance fluids at 70-80% of maintenance, IV salbutamol (watch potassium + ECG), epinephrine IM/SC, magnesium sulphate 25-75 mg/kg (max 2.5 g) IV over 20 min, aminophylline, inhaled heliox, mechanical ventilation.', 'Critically ill asthma requires intensive and multimodal therapy (BNR-0011).', TRUE),
   ('c841fd5e-ff3a-5e64-9f7d-c05147cbb5ac', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-09', 'Resolve exacerbation and step down', 'treatment', '90', 'When improved: space SABA gradually to every 3-4 hours; continue steroids for the full 3-7 days; start controller therapy.', 'Steroid taper and controller introduction prevent early relapse (BNR-0012).', TRUE),
   ('01bdf3cf-4059-5e17-a7aa-6ba78e667dec', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-10', 'Issue written action plan', 'education', '100', 'Give the family/patient a written action plan for recognition and management of future exacerbations; for life-threatening (especially abrupt-onset) episodes consider an epinephrine autoinjector and portable oxygen at home.', 'Every child/family with asthma should have a written action plan (BNR-0012).', TRUE),
   ('a64444f3-9857-59ff-8fcd-58ccafa09f84', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-11', 'Educate on inhaler technique and triggers', 'education', '110', 'Teach spacer/MDI technique, trigger avoidance, correct use of reliever vs controller, and when to seek urgent care.', 'Education improves adherence and reduces exacerbation risk.', TRUE),
   ('bc4b3a30-c4bc-5600-b1a2-7993758620a4', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), 'STEP-12', 'Close the care loop', 'follow_up', '120', 'Record severity, treatment given, response, discharge plan and follow-up; schedule controller review.', 'The episode generates continuity rather than terminating at discharge.', TRUE)
