   ('4820a876-7b59-5fd4-bf1d-a6ef1b5b25b3', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-04'), 'medicate', 'MED-IPRATROPIUM', 'Ipratropium bromide (SAMA)', '125-250 mcg neb if no response to first salbutamol', 'immediate', '20'),
   ('49e233d3-1297-56b5-a338-6cbab57e56c0', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-04'), 'medicate', 'MED-PREDNISOLONE', 'Prednisolone', '1-2 mg/kg in moderate-severe exacerbations', 'urgent', '30'),
   ('e7ce9321-ac8a-5a40-8d0e-aada67ce67f8', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-04'), 'medicate', 'MED-EPINEPHRINE', 'Epinephrine', '0.3-0.5 mg IM/SC in severe cases', 'immediate', '40'),
   ('54885d81-a4fa-5898-9c92-e44530600953', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-05'), 'monitor', 'MON-PEF', 'Peak expiratory flow', 'Target PEF >70% predicted/personal best at 1 hour', 'urgent', '10'),
   ('731b2ea4-6c11-508b-990d-1eb82942dff2', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-05'), 'monitor', 'MON-SPO2', 'Oxygen saturation monitoring', 'Target SpO2 >92% in room air for 4 hours', 'urgent', '20'),
   ('fafc8df3-642f-5857-8e71-cfcb108d09b7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-07'), 'medicate', 'MED-SALBUTAMOL', 'Salbutamol (SABA)', 'Nebulizer every 20 min then every 1-4 hr, or continuous 5-15 mg/hr', 'urgent', '10'),
   ('ba3c5211-f68c-52b2-bcdd-65463aabc4a1', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-07'), 'medicate', 'MED-PREDNISOLONE', 'Prednisolone', '1-2 mg/kg oral or parenteral methylprednisolone/hydrocortisone, 3-7 days', 'urgent', '20'),
   ('0ba993a4-dd97-5cb3-bac0-e46134bb8c5a', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-08'), 'medicate', 'MED-MAGNESIUM-SULPHATE', 'Magnesium sulphate', '25-75 mg/kg IV over 20 min (max 2.5 g)', 'urgent', '10'),
   ('d064ef57-cfc4-5d13-8a7c-1d3826968e74', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-08'), 'medicate', 'MED-AMINOPHYLLINE', 'Aminophylline', 'Loading 5-10 mg/kg over 1 hr, then 1 mg/kg/hr (0.7 if >10y)', 'urgent', '20'),
   ('65447609-1fb2-5fff-8e87-760822a4cae3', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-08'), 'medicate', 'MED-EPINEPHRINE', 'Epinephrine', '0.3-0.5 mg IM/SC for critically ill', 'urgent', '30'),
   ('08892aca-7758-52fc-8d10-a069f0838ada', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-10'), 'educate', 'EDU-ASTHMA-ACTION-PLAN', 'Asthma written action plan', 'Recognition and management of exacerbations; epinephrine autoinjector if life-threatening history', 'routine', '10'),
   ('a1ddf558-3bba-5561-97f6-71cad285456b', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-ASTHMA-INHALER-TECHNIQUE', 'Inhaler technique', 'Spacer/MDI technique and reliever vs controller use', 'routine', '10'),
   ('766b936f-936d-5721-bf6a-61716b32dd11', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-ASTHMA-ACUTE'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-ASTHMA-ACUTE' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-ASTHMA-TRIGGERS', 'Asthma triggers', 'Identify and avoid individual triggers', 'routine', '20'),
