INSERT INTO knowledge.education (id, concept_id, education_code, title, audience, content_type, language_code, literacy_level, body, status) VALUES
   ('014e2936-cd71-5c3c-aaf0-23f550b26aa8', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-ASTHMA-ACTION-PLAN'), 'EDU-ASTHMA-ACTION-PLAN', 'Written asthma action plan', 'caregiver', 'discharge', 'en', 'plain', 'A written plan for recognizing and managing asthma exacerbations: which medicines to take when symptoms worsen, when to seek urgent care, and home epinephrine/oxygen for life-threatening history (BNR-0012).', 'active'),
   ('894d1b9f-30bc-5ef1-a4c1-59933f9dd8a1', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-ASTHMA-INHALER-TECHNIQUE'), 'EDU-ASTHMA-INHALER-TECHNIQUE', 'Correct inhaler technique', 'patient', 'instruction', 'en', 'plain', 'Use a spacer with MDI: shake, insert, one puff, breathe in slowly and hold; reliever (salbutamol) for acute symptoms, controller (ICS) daily regardless of symptoms.', 'active'),
   ('354e32bc-7fef-5e85-94ba-e4de0a893c24', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-ASTHMA-TRIGGERS'), 'EDU-ASTHMA-TRIGGERS', 'Asthma trigger avoidance', 'patient', 'explanation', 'en', 'plain', 'Identify and avoid triggers such as viral infections, allergens, exercise, cold air and smoke; keep reliever available.', 'active'),
   ('73df41e7-f3fb-54b8-8697-84108e1c5855', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-ASTHMA-TEACHBACK'), 'EDU-ASTHMA-TEACHBACK', 'Asthma teach-back', 'caregiver', 'teach_back', 'en', 'plain', 'Confirm the patient/family can demonstrate inhaler use and describe when to seek urgent care before discharge.', 'active'),
   ('8e090d0d-860f-5aa6-920b-af4227ebabb7', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-ASTHMA-CLINICIAN'), 'EDU-ASTHMA-CLINICIAN', 'Asthma reasoning summary', 'clinician', 'explanation', 'en', 'plain', 'Render the acute asthma severity grade, evidence, phenotype comparison and the treatment/escalation rationale.', 'active')
