INSERT INTO governance.knowledge_object (id, object_code, knowledge_type, canonical_name, description, source_claim_code, jurisdiction_code, population_code, evidence_level_code, lifecycle_status, confidence, is_active, status) VALUES
   ('ba89ec98-0e7c-52bb-82e4-c828aec35369', 'PROT-ASTHMA-ACUTE', 'PROTOCOL', 'Acute asthma pathway', 'Population-aware (paediatric + adult) acute asthma exacerbation pathway: severity grading, emergency treatment, monitoring, escalation, disposition, written action plan, education.', 'BNR-0009', 'JUR-GLOBAL', 'POP-BOTH', 'EV-C', 'ACTIVE', 0.95, true, 'active'),
   ('781b6303-a84b-5cc6-80f1-0299365d6f87', 'MED-SALBUTAMOL', 'DRUG', 'Salbutamol (acute asthma)', 'SABA bronchodilator for acute asthma exacerbation (BNR-0009).', 'BNR-0009', 'JUR-GLOBAL', 'POP-BOTH', 'EV-C', 'ACTIVE', 0.95, true, 'active'),
